#!/dd/CMDS/bash# keep -- take a program off the collection and onto your own disk.## The collection is meant to be RUN IN PLACE, mounted as /h0. When a program# earns its place you `keep' it and it is copied to your own disk. Nothing is# installed behind your back; nothing happens that you did not ask for.##   keep <name>...     the program, and whatever DOC/DEPENDS says it needs#   keep -n <name>...  dry run: say what would be written, touch nothing#   keep -f <name>...  overwrite what is already there (otherwise refused)#   kept               what has been taken so far#   drop <name>...     put back exactly what keep wrote## Every file written is recorded in SYS/kept with its size and MD5. That is# what makes `drop' safe: it removes only files it wrote, and refuses any# whose checksum has changed, so your saves and scores cannot be eaten.## WRITTEN FOR THIS BASH, WHICH HAS THREE TRAPS:#   * command substitution does not inherit PATH and cannot see functions,#     so there is none here at all -- output goes to a file and `read' (a#     builtin) picks it up#   * there is no /dev/null; OS-9's bit bucket is /nil#   * mkdir will not create parents, so each component is made in turnC=/dd/CMDSFROM=${KEEP_FROM:-/h0}TO=${KEEP_TO:-/dd}RECEIPT=$TO/SYS/keptW=$TO/tmp/keep$$dry=no; force=nowhile :; do  case ${1:-} in    -n) dry=yes; shift ;;    -f) force=yes; shift ;;    -*) echo "keep: unknown option $1"; exit 1 ;;     *) break ;;  esacdoneif [ -z "${1:-}" ]; then  echo "usage: keep [-n] [-f] <name>...   take a program onto your disk"  echo "       kept                       what has been taken"  echo "       drop <name>...             put it back"  exit 1fifor prog in "$@"; do  rel=""  for d in CMDS CMDS/GAMES CMDS/NETPBM CMDS/UUCP CMDS/REBUILT CMDS/DEMOS CMDS/DHRY CMDS/MM1; do    if [ -z "$rel" ] && $C/ls $FROM/$d/$prog > /nil 2>/nil; then rel=$d/$prog; fi  done  if [ -z "$rel" ]; then    echo "keep: no program called '$prog' in this collection"    continue  fi  # the program, then any data file DOC/DEPENDS names for it that is here  echo "$FROM/$rel	$TO/$rel" > $W.f  # DOC/DEPENDS is blocks: "  <name>   (dir)" then indented absolute paths.  # Parsed here in bash -- this awk will not take a multi-line program.  : > $W.d  inblk=no  while read -r a1 a2; do    case $a1 in      /*) if [ "$inblk" = yes ]; then echo "$a1" >> $W.d; fi ;;       "") ;;       *)  if [ "$a1" = "$prog" ]; then inblk=yes; else inblk=no; fi ;;    esac  done < $FROM/DOC/DEPENDS  while read -r p; do    tail=""    case $p in      /dd/*) tail=${p#/dd/} ;;      /h0/*) tail=${p#/h0/} ;;    esac    if [ -n "$tail" ] && $C/ls $FROM/$tail > /nil 2>/nil; then      echo "$FROM/$tail	$TO/$tail" >> $W.f    fi  done < $W.d  # the same file can be named twice (a program that wants /dd/sys/termcap  # AND /h0/sys/termcap is asking for one file), so take each destination once  $C/sort -u $W.f > $W.u  while IFS="	" read -r src dst; do    if $C/ls $dst > /nil 2>/nil && [ "$force" = no ]; then      echo "keep: $dst is already there -- not overwritten (use -f)"      continue    fi    if [ "$dry" = yes ]; then      echo "would write $dst"      continue    fi    # make each directory component in turn; mkdir here has no -p    d=${dst%/*}    if ! $C/ls -d $d > /nil 2>/nil; then      made=""      rest=${d#/}      while [ -n "$rest" ]; do        part=${rest%%/*}        made=$made/$part        if ! $C/ls -d $made > /nil 2>/nil; then $C/mkdir "$made" > /nil 2>/nil; fi        if [ "$rest" = "$part" ]; then rest=""; else rest=${rest#*/}; fi      done    fi    $C/cp "$src" "$dst" > /nil 2>/nil    if $C/ls "$dst" > /nil 2>/nil; then      $C/md5 "$dst" > $W.m      read m1 m2 m3 sum < $W.m      $C/ls -l "$dst" > $W.s      read s1 s2 s3 s4 sz srest < $W.s      echo "$prog	$dst	$sz	$sum" >> "$RECEIPT"      echo "kept $dst"    else      echo "keep: could not take $src (a directory, or unreadable) -- skipped"    fi  done < $W.udone$C/rm $W.f $W.u $W.d $W.m $W.s > /nil 2>/nil